<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {Database,LayoutDashboard,FolderOpen,Search,RefreshCw,ChevronRight,ArrowRight,ArrowUpRight,ShieldCheck,LockKeyhole,LoaderCircle,X,FileText,Table2,Layers3,CalendarClock,Server,Tag,Image,Download,Eye,AlertCircle,CheckCircle2,ChevronLeft} from 'lucide-vue-next';
import {appUrl} from '../lib/urls';
type Item=Record<string,any>;
const props=defineProps<{tenants:Item[];connected:boolean;userId:number;role:string;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{project:[id:string];connect:[]}>();
const tenant=ref('');const snapshot=ref<Item|null>(null);const loading=ref(false);const error=ref('');const kind=ref('app');const search=ref('');const scope=ref('all');const desk=ref('');const tag=ref('');const page=ref(1);const selected=ref<Item|null>(null);const detail=ref<Item|null>(null);const detailLoading=ref(false);const detailError=ref('');const creating=ref(false);const dashboard=ref('');const image=ref('');const imageLoading=ref(false);const dataLoading=ref(false);const preview=ref<Item|null>(null);const tab=ref('overview');
let requestVersion=0;
const kinds=[{id:'app',label:'Aplicações',icon:LayoutDashboard},{id:'bi-desk',label:'Mesas de aplicações',icon:FolderOpen},{id:'dw-desk',label:'Mesas de dados',icon:Layers3},{id:'table',label:'Tabelas',icon:Table2},{id:'flow',label:'Fontes / ETL',icon:Database},{id:'schedule',label:'Agendas',icon:CalendarClock},{id:'agent',label:'Agentes',icon:Server},{id:'writeback',label:'Cadastros',icon:Table2},{id:'deck',label:'Decks',icon:FileText},{id:'presentation',label:'Apresentações',icon:Image},{id:'investigation',label:'Investigações',icon:Search},{id:'credential',label:'Conexões de dados',icon:LockKeyhole},{id:'variables',label:'Variáveis',icon:Tag}];
const rows=computed<Item[]>(()=>snapshot.value?.resources?.[kind.value]??[]);
const capability=computed(()=>snapshot.value?.capabilities?.[kind.value]);
const desks=computed<Item[]>(()=>snapshot.value?.resources?.[kind.value==='app'?'bi-desk':'dw-desk']??[]);
const deskNames=computed(()=>Object.fromEntries(desks.value.map(d=>[d.id,d.name])));
const filtered=computed(()=>rows.value.filter(row=>{const text=[row.name,row.description,row.ref,...(row.tags??[]),...(row.dashboards??[]).map((d:Item)=>d.name)].join(' ').toLocaleLowerCase('pt-BR');return(!search.value||text.includes(search.value.toLocaleLowerCase('pt-BR')))&&(scope.value==='all'||row.state===scope.value)&&(!desk.value||row.desk_id===desk.value)&&(!tag.value||row.tags.includes(tag.value));}));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/18)));const visible=computed(()=>filtered.value.slice((page.value-1)*18,page.value*18));
const appStats=computed(()=>{const apps=snapshot.value?.resources?.app??[];return {all:apps.length,mine:apps.filter((a:Item)=>a.state==='draft').length,published:apps.filter((a:Item)=>a.state==='published').length};});
const dashboardList=computed<Item[]>(()=>detail.value?.resource?.dashboards??[]);
const unavailable=computed(()=>Object.values(snapshot.value?.capabilities??{}).filter((c:any)=>c.status!=='available').length);
const widgets=computed<Item[]>(()=>preview.value?.data?.widgets??[]);
watch([search,scope,desk,tag,kind],()=>page.value=1);
watch(kind,()=>{scope.value='all';desk.value='';tag.value='';});
watch(tenant,()=>{if(tenant.value){localStorage.setItem('g-analise:tenant:'+props.userId,tenant.value);load();}else snapshot.value=null;});
function label(state:string){return ({draft:'Minha Mesa',published:'Publicado',active:'Ativo',inactive:'Inativo',available:'Disponível',access_denied:'Sem permissão',unavailable:'Indisponível'} as Record<string,string>)[state]??state;}
async function load(refresh=false){const version=++requestVersion;loading.value=true;error.value='';snapshot.value=null;try{const result=await props.request(`/catalog/${tenant.value}${refresh?'?refresh=1':''}`);if(version===requestVersion)snapshot.value=result;}catch(e){if(version===requestVersion)error.value=(e as Error).message;}finally{if(version===requestVersion)loading.value=false;}}
function clearImage(){if(image.value)URL.revokeObjectURL(image.value);image.value='';}
async function open(row:Item){clearImage();selected.value=row;detail.value=null;preview.value=null;tab.value='overview';dashboard.value='';detailError.value='';detailLoading.value=true;try{detail.value=await props.request(row.kind==='variables'?`/catalog/${tenant.value}/variables/${row.id}`:`/catalog/${tenant.value}/resources/${row.kind}/${row.id}`);if(dashboardList.value.length)dashboard.value=String(dashboardList.value[0].id??'');}catch(e){detailError.value=(e as Error).message;}finally{detailLoading.value=false;}}
function close(){selected.value=null;clearImage();}
async function project(){if(!selected.value)return;creating.value=true;detailError.value='';try{const result=await props.request(`/catalog/${tenant.value}/projects`,'POST',{resource:selected.value.ref});close();emit('project',result.project.id);}catch(e){detailError.value=(e as Error).message;}finally{creating.value=false;}}
async function loadImage(){if(!selected.value)return;tab.value='image';imageLoading.value=true;detailError.value='';clearImage();try{const response=await fetch(appUrl(`/api/catalog/${tenant.value}/apps/${selected.value.id}/image${dashboard.value?'?dashboard='+encodeURIComponent(dashboard.value):''}`),{credentials:'same-origin',headers:{Accept:'image/png'}});if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.message??'Não foi possível gerar a prévia visual.');}image.value=URL.createObjectURL(await response.blob());}catch(e){detailError.value=(e as Error).message;}finally{imageLoading.value=false;}}
async function loadData(){if(!selected.value)return;tab.value='data';dataLoading.value=true;preview.value=null;detailError.value='';try{preview.value=await props.request(`/catalog/${tenant.value}/apps/${selected.value.id}/preview${dashboard.value?'?dashboard='+encodeURIComponent(dashboard.value):''}`);}catch(e){detailError.value=(e as Error).message;}finally{dataLoading.value=false;}}
function widgetRows(widget:Item):any[]{return widget.rows??widget.data?.rows??(Array.isArray(widget.data)?widget.data:[]);}
function keydown(e:KeyboardEvent){if(e.key==='Escape')close();}
onMounted(()=>{window.addEventListener('keydown',keydown);const saved=localStorage.getItem('g-analise:tenant:'+props.userId);if(saved&&props.tenants.some(t=>String(t.id)===saved))tenant.value=saved;});
onUnmounted(()=>{clearImage();window.removeEventListener('keydown',keydown);});
</script>

<template>
<div class="content-view catalog-view">
 <div class="page-heading"><div><div class="section-eyebrow">SEUS DADOS, SUAS APLICAÇÕES</div><h1>Catálogo BI</h1><p>Explore o G-Analise e escolha onde quer trabalhar.</p></div><span class="soft-badge"><ShieldCheck :size="15"/> Acesso com as suas permissões</span></div>
 <div v-if="!connected" class="empty-state bordered"><Database :size="36"/><h3>Conecte seu G-Analise BI</h3><p>Seus tenants, aplicações e fontes aparecerão aqui.</p><button class="primary-button" @click="emit('connect')">Configurar conexão <ArrowRight :size="15"/></button></div>
 <template v-else>
  <div class="catalog-tenant-bar"><label><Database :size="18"/><span>Tenant</span><select v-model="tenant" aria-label="Tenant do catálogo"><option value="">Selecione um tenant</option><option v-for="t in tenants" :key="t.id" :value="String(t.id)">{{t.name}}</option></select></label><span v-if="snapshot?.tenant.read_only" class="catalog-readonly"><LockKeyhole :size="14"/> Somente leitura</span><button class="secondary-button" :disabled="!tenant||loading" @click="load(true)"><RefreshCw :size="15" :class="{spin:loading}"/> Atualizar catálogo</button></div>
  <div v-if="loading" class="catalog-loading"><LoaderCircle :size="26" class="spin"/><h3>Consultando seu catálogo</h3><p>A primeira consulta pode levar alguns instantes.<br>Estamos conferindo os recursos disponíveis para sua conta.</p><div class="catalog-skeleton"><i v-for="i in 3" :key="i"></i></div></div>
  <div v-else-if="error" class="catalog-error"><AlertCircle :size="23"/><div><strong>Não foi possível carregar o catálogo</strong><p>{{error}}</p><button class="secondary-button" @click="load(true)">Tentar novamente</button></div></div>
  <div v-else-if="!tenant" class="empty-state bordered"><FolderOpen :size="35"/><h3>Escolha um tenant para começar</h3><p>Você pode consultar aplicações publicadas, sua mesa e as fontes de dados de cada ambiente.</p></div>
  <template v-else-if="snapshot">
   <div v-if="snapshot.tenant.read_only" class="catalog-policy"><ShieldCheck :size="18"/><div><strong>Ambiente protegido para consulta</strong><span>Você pode explorar e visualizar. Alterações, publicações e execuções estão bloqueadas neste tenant.</span></div></div>
   <div class="catalog-stat-grid"><button :class="{active:kind==='app'&&scope==='all'}" @click="kind='app';scope='all'"><LayoutDashboard :size="20"/><span>Aplicações</span><strong>{{appStats.all}}</strong></button><button :class="{active:kind==='app'&&scope==='draft'}" @click="kind='app';scope='draft'"><FolderOpen :size="20"/><span>Minha Mesa</span><strong>{{appStats.mine}}</strong></button><button :class="{active:kind==='app'&&scope==='published'}" @click="kind='app';scope='published'"><CheckCircle2 :size="20"/><span>Publicadas</span><strong>{{appStats.published}}</strong></button><button @click="kind='table'"><Table2 :size="20"/><span>Tabelas</span><strong>{{snapshot.capabilities.table.count??'—'}}</strong></button></div>
   <div class="catalog-body"><aside class="catalog-kind-nav"><button v-for="item in kinds" :key="item.id" :class="{active:kind===item.id}" @click="kind=item.id"><component :is="item.icon" :size="16"/><span>{{item.label}}</span><small>{{snapshot.capabilities[item.id]?.count??'—'}}</small></button></aside>
    <div class="catalog-results"><div class="catalog-filters"><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="Busque por nome, dashboard ou etiqueta…" aria-label="Buscar no catálogo"></div><select v-if="['app','table','flow','writeback'].includes(kind)" v-model="scope" aria-label="Situação do recurso"><option value="all">Todas as situações</option><option value="draft">Minha Mesa</option><option value="published">Publicados</option></select><select v-if="desks.length&&['app','table','flow'].includes(kind)" v-model="desk" aria-label="Mesa do recurso"><option value="">Todas as mesas</option><option v-for="d in desks" :key="d.id" :value="d.id">{{d.name}}</option></select><select v-if="snapshot.tags.length" v-model="tag" aria-label="Etiqueta do recurso"><option value="">Todas as etiquetas</option><option v-for="t in snapshot.tags" :key="t">{{t}}</option></select></div>
     <div class="catalog-result-heading"><h2>{{kinds.find(k=>k.id===kind)?.label}}</h2><span>{{filtered.length}} {{filtered.length===1?'recurso':'recursos'}}</span></div>
     <div v-if="capability?.status!=='available'" class="catalog-error compact"><LockKeyhole :size="23"/><div><strong>{{label(capability?.status)}}</strong><p>{{capability?.reason}}</p></div></div>
     <div v-else-if="!filtered.length" class="empty-state bordered"><FolderOpen :size="30"/><h3>{{rows.length?'Nenhum resultado para esses filtros':'Nenhum recurso nesta área'}}</h3><p>{{rows.length?'Tente outro termo ou remova os filtros.':'Os recursos disponíveis para sua conta aparecerão aqui.'}}</p></div>
     <div v-else class="catalog-resource-grid"><button v-for="row in visible" :key="row.ref" class="catalog-resource" @click="open(row)"><div class="catalog-resource-head"><span class="project-icon small blue"><component :is="kinds.find(k=>k.id===kind)?.icon??Database" :size="19"/></span><span v-if="row.state" class="catalog-state" :class="row.state">{{label(row.state)}}</span><ArrowUpRight :size="16"/></div><h3>{{row.name}}</h3><p>{{row.description||((row.desk_id&&deskNames[row.desk_id])?deskNames[row.desk_id]:row.state==='draft'?'Aplicação ou recurso da sua mesa':row.ref)}}</p><div class="catalog-tags"><span v-for="t in row.tags.slice(0,3)" :key="t"><Tag :size="10"/>{{t}}</span></div><footer><span v-if="row.kind==='app'"><LayoutDashboard :size="13"/>{{row.dashboard_count===null?'Ver dashboards':row.dashboard_count+(row.dashboard_count===1?' dashboard':' dashboards')}}</span><span v-else>{{row.ref}}</span><ChevronRight :size="15"/></footer></button></div>
     <div v-if="pages>1" class="catalog-pagination"><span>Página {{page}} de {{pages}}</span><button class="secondary-button" :disabled="page===1" @click="page--"><ChevronLeft :size="14"/> Anterior</button><button class="secondary-button" :disabled="page===pages" @click="page++">Próxima <ChevronRight :size="14"/></button></div>
    </div>
   </div>
   <p class="catalog-footnote">Atualizado em {{new Date(snapshot.synced_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}} · Brasília. O catálogo inclui os recursos autorizados retornados pelo G-Analise.</p><p v-if="unavailable" class="catalog-footnote">{{unavailable}} áreas não estão disponíveis nesta consulta. Consulte cada área para conferir o motivo.</p><p v-for="warning in snapshot.warnings" :key="warning" class="catalog-footnote">{{warning}}</p>
  </template>
 </template>
 <div v-if="selected" class="modal-backdrop" @click.self="close"><section class="modal catalog-detail" role="dialog" aria-modal="true" :aria-label="selected.name"><button class="modal-close icon-button" aria-label="Fechar recurso" @click="close"><X :size="19"/></button><div class="catalog-detail-heading"><span class="project-icon blue"><LayoutDashboard :size="23"/></span><div><span>{{selected.ref}}</span><h2>{{detail?.resource.name??selected.name}}</h2><p>{{snapshot?.tenant.name}} · {{label(detail?.resource.state??selected.state)}}</p></div></div>
  <div v-if="detailLoading" class="catalog-loading"><LoaderCircle :size="24" class="spin"/><p>Carregando detalhes…</p></div><div v-if="detailError" class="form-error" role="alert"><AlertCircle :size="17"/>{{detailError}}</div>
  <template v-if="detail"><p v-if="detail.resource.description" class="catalog-detail-description">{{detail.resource.description}}</p><div v-if="selected.kind==='app'" class="catalog-preview-controls"><label>Dashboard<select v-model="dashboard" aria-label="Dashboard da aplicação"><option v-if="!dashboardList.length" value="">Principal</option><option v-for="(d,index) in dashboardList" :key="d.id??index" :value="String(d.id??'')">{{d.name}}</option></select></label><button class="secondary-button" :disabled="imageLoading||dataLoading" @click="loadImage"><Image :size="16"/> Prévia visual</button><button class="secondary-button" :disabled="imageLoading||dataLoading" @click="loadData"><Table2 :size="16"/> Conferir dados</button></div>
   <div v-if="tab==='image'" class="catalog-image-preview"><div v-if="imageLoading" class="catalog-loading"><LoaderCircle :size="25" class="spin"/><p>Gerando a prévia real do dashboard…</p></div><template v-if="image"><img :src="image" alt="Prévia real do dashboard selecionado"><a class="secondary-button" :href="image" :download="selected.name+'.png'"><Download :size="15"/> Baixar PNG</a></template></div>
   <div v-else-if="tab==='data'" class="catalog-data-preview"><div v-if="dataLoading" class="catalog-loading"><LoaderCircle :size="23" class="spin"/><p>Consultando os dados dos widgets…</p></div><article v-for="widget in widgets" :key="widget.widget_id" class="catalog-widget-data"><div><strong>{{widget.nome||'Widget '+widget.widget_id}}</strong><span>{{widget.type}}</span></div><p v-if="widget.reason||widget.error">{{widget.reason||widget.error}}</p><div v-if="widgetRows(widget).length" class="catalog-table-scroll"><table><tbody><tr v-for="(row,index) in widgetRows(widget).slice(0,20)" :key="index"><td v-for="(value,column) in row" :key="column">{{value}}</td></tr></tbody></table></div><p v-else-if="!widget.reason&&!widget.error">{{widget.status==='ok'?'Consulta concluída sem linhas.':widget.status}}</p></article><p v-if="preview&&!widgets.length" class="catalog-footnote">A aplicação não retornou widgets para esta prévia.</p></div>
   <p v-if="detail.metadata_complete===false" class="catalog-footnote" role="note">{{detail.metadata_message}}</p><div v-if="tab==='overview'" class="catalog-detail-overview"><div class="catalog-detail-facts"><span v-if="detail.resource.dashboard_count!==null"><strong>{{detail.resource.dashboard_count}}</strong> dashboards</span><span v-if="detail.resource.table_count!==null"><strong>{{detail.resource.table_count}}</strong> tabelas vinculadas</span><span v-if="detail.resource.active!==null"><strong>{{detail.resource.active?'Ativo':'Inativo'}}</strong> estado da agenda/recurso</span></div><div v-if="dashboardList.length" class="catalog-dashboard-list"><h3>Dashboards desta aplicação</h3><button v-for="(d,index) in dashboardList" :key="d.id??index" @click="dashboard=String(d.id??'');loadImage()"><LayoutDashboard :size="17"/><strong>{{d.name}}</strong><span>{{d.widget_count}} widgets</span><ChevronRight :size="15"/></button></div><details class="catalog-technical"><summary>Detalhes do recurso</summary><pre>{{JSON.stringify(detail.details,null,2)}}</pre></details></div>
   <div class="modal-footer"><span v-if="detail.tenant.read_only" class="catalog-readonly"><LockKeyhole :size="14"/> Somente leitura</span><button class="secondary-button" @click="close">Fechar</button><button v-if="role!=='viewer'&&['app','flow','table','schedule'].includes(selected.kind)" class="primary-button" :disabled="creating" @click="project"><LoaderCircle v-if="creating" :size="16" class="spin"/>{{detail.tenant.read_only?'Abrir projeto de análise':'Trabalhar neste recurso'}}<ArrowRight :size="15"/></button></div>
  </template>
 </section></div>
</div>
</template>
